import json
from pathlib import Path

from .merkle import leaf_hash, merkle_proof, merkle_root, verify_proof

__all__ = ["State"]

STATE_FILE = "state.json"


def _leaf(account: str, balance: int) -> bytes:
    return leaf_hash(f"{account}:{balance}".encode("utf-8"))


